INSERT INTO origins (id, slug, name, region, lat, lng) VALUES
  (1, 'ortisei', 'Ortisei', 'Val Gardena · Dolomites', 46.5747, 11.6717);
INSERT INTO trails (origin_id, slug, name, area, trail_no, difficulty, length_km, ascent_m, duration_h, peak_m, peak_name, massif, access, start_lat, start_lng, peak_lat, peak_lng, path, blurb) VALUES
  (1, 'seceda-ridge', 'Seceda Ridge Viewpoint', 'Puez-Odle Nature Park', 'Ridge loop', 'easy', 1.3, 110, 0.75, 2519, 'Seceda', 'Odle / Geisler', 'Seceda cable car from Ortisei', 46.6064, 11.6536, 46.6086, 11.65, '[[46.6064,11.6536],[46.6072,11.6521],[46.6082,11.6508],[46.6086,11.65],[46.6076,11.6489]]', 'The postcard of the Dolomites: the knife-edge Seceda ridge tilting up to the jagged Odle spires. A short, easy stroll from the top of the cable car to the famous viewpoint, with the Sella and Sassolungo on the horizon.'),
  (1, 'panascharte', 'Panascharte (Forcella Pana)', 'Puez-Odle Nature Park', 'No. 35 / 1', 'medium', 8, 480, 3, 2447, 'Forcella Pana', 'Odle / Geisler', 'Resciesa funicular from Ortisei', 46.5899, 11.6852, 46.6033, 11.6586, '[[46.5899,11.6852],[46.5955,11.674],[46.6011,11.6662],[46.6033,11.6586],[46.6062,11.6541]]', 'One of the most popular ridge traverses in the valley. From the Resciesa plateau the path runs west under the full sawtooth wall of the Odle to the Pana saddle, then drops onto the Seceda alp. Start early — it gets busy by mid-morning.'),
  (1, 'adolf-munkel', 'Adolf Munkel Trail (Via delle Odle)', 'Puez-Odle Nature Park', 'No. 35 / 36', 'medium', 9.2, 428, 3.5, 2006, 'Gschnagenhardt Alm', 'Odle / Geisler (Sass Rigais 3025 m)', 'Zans trailhead, Val di Funes', 46.6353, 11.7045, 46.6125, 11.6822, '[[46.6353,11.7045],[46.625,11.6961],[46.6171,11.6889],[46.6125,11.6822],[46.6112,11.674]]', 'A near-level forest-and-meadow circuit along the northern base of the Geisler/Odle group, named after the Dresden alpinist who founded it in 1905. The sawtooth peaks rise straight overhead from the Geisler Alm "cinema" — manageable for most and even doable with kids.'),
  (1, 'raschoetz-promenade', 'Raschötz High Promenade', 'Resciesa / Raschötz', 'No. 31 / 1 / 10', 'easy', 5, 200, 2, 2281, 'Außerraschötz cross', 'Puez-Geisler panorama', 'Resciesa funicular from Ortisei', 46.5899, 11.6852, 46.5972, 11.6928, '[[46.5899,11.6852],[46.5931,11.6889],[46.5972,11.6928],[46.5958,11.6961],[46.5919,11.6925]]', 'Sunny, gentle high-level walking on the Raschötz ridge with a 360° sweep over the Puez-Geisler park to the summit cross at 2,281 m, then down past the Heilig-Kreuz chapel. A relaxed family favourite straight off the funicular.'),
  (1, 'col-raiser-firenze', 'Col Raiser → Rifugio Firenze', 'Puez-Odle Nature Park', 'No. 1', 'easy', 5, 160, 2, 2090, 'Rifugio Firenze', 'Fermeda / Odle', 'Col Raiser gondola from S. Cristina', 46.5887, 11.7047, 46.6056, 11.6647, '[[46.5887,11.7047],[46.595,11.6922],[46.6005,11.6788],[46.6056,11.6647]]', 'An easy, gradual walk across open alp from the top of the Col Raiser gondola to the Regensburger Hütte (Rifugio Firenze, 2,037 m), tucked right beneath the Fermeda towers. Big-mountain scenery with very little effort.'),
  (1, 'alpe-di-siusi', 'Alpe di Siusi Meadow Walk', 'Seiser Alm / Sciliar', 'Meadow paths', 'easy', 6, 150, 2.5, 2005, 'Mont Sëuc', 'Sassolungo & Sciliar views', 'Mont Sëuc cable car from Ortisei', 46.5497, 11.6436, 46.5419, 11.6147, '[[46.5497,11.6436],[46.5468,11.6331],[46.5441,11.6238],[46.5419,11.6147]]', 'Europe’s largest high-altitude alpine meadow, rolling green under the Sassolungo and Sciliar. Wide, almost flat paths make this the easiest big-view day from Ortisei — perfect for a slow afternoon or a picnic.'),
  (1, 'sassolungo-circuit', 'Sassolungo Circuit (Friedrich-August-Weg)', 'Sassolungo / Langkofel', 'No. 557 / 4', 'medium', 11, 600, 5.5, 2300, 'Rif. Friedrich August', 'Sassolungo 3181 m', 'Passo Sella (bus/drive via Selva)', 46.5099, 11.7556, 46.5125, 11.7361, '[[46.5099,11.7556],[46.5111,11.7459],[46.5125,11.7361],[46.5172,11.7301],[46.5219,11.736]]', 'A grand loop right around the base of the Sassolungo/Langkofel massif, weaving between rock towers, scree and high pasture with the Friedrich-August hut along the way. A proper full day of moderate alpine walking.'),
  (1, 'sass-rigais', 'Sass Rigais Summit (via ferrata)', 'Puez-Odle Nature Park', 'No. 2 / via ferrata', 'hard', 9, 900, 6, 3025, 'Sass Rigais', 'Odle / Geisler', 'Col Raiser gondola from S. Cristina', 46.5887, 11.7047, 46.6131, 11.6917, '[[46.5887,11.7047],[46.5972,11.6986],[46.6048,11.6948],[46.6131,11.6917]]', 'The roof of the Odle group at 3,025 m, reached by a cabled via-ferrata line through the heart of the massif. Exposed, steep and serious — for experienced scramblers with a helmet, harness and a head for heights only.'),
  (1, 'resciesa-seceda-traverse', 'Resciesa → Brogles → Seceda Traverse', 'Puez-Odle Nature Park', 'No. 35 / 29', 'hard', 14.4, 1087, 6.25, 2519, 'Seceda ridge', 'Odle / Geisler', 'Resciesa funicular → Seceda cableway', 46.5899, 11.6852, 46.6075, 11.6533, '[[46.5899,11.6852],[46.6051,11.6884],[46.6142,11.6803],[46.6125,11.6685],[46.6075,11.6533]]', 'A big point-to-point that links the two Ortisei high plateaus: up onto Resciesa, along the Adolf Munkel base, over the steep Furcela de Mesdi scree, then up to the Seceda ridge. Over 1,000 m of climbing and the most demanding day here.'),
  (1, 'gran-cir', 'Gran Cir via Passo Gardena', 'Puez-Odle Nature Park', 'No. 2', 'medium', 4.7, 450, 2.5, 2592, 'Gran Cir (Große Cirspitze)', 'Cir Group / Puez', 'Drive SS243 from Selva to Passo Gardena (2,121 m)', 46.5498, 11.8084, 46.5585, 11.8055, '[[46.5498,11.8084],[46.5519,11.8072],[46.5542,11.8061],[46.5561,11.805],[46.5575,11.8053],[46.5585,11.8055]]', 'A short, rewarding climb from Passo Gardena up trail no. 2 through meadow and scree, finishing on an easy cable-protected via ferrata. From the 2,592 m cross: a sweeping panorama over the Sella, Sassolungo and Puez groups.'),
  (1, 'col-de-la-puina', 'Col de la Puina', 'Val di Zoldo / Pelmo', 'CAI 467 + ridge', 'easy', 7.3, 600, 3.5, 2254, 'Col de la Puina', 'Pelmo', 'Drive via Passo Staulanza; park at the hairpin (~1,663 m)', 46.4283, 12.1139, 46.4436, 12.1303, '[[46.4283,12.1139],[46.4365,12.1135],[46.4369,12.1226],[46.44,12.1265],[46.4436,12.1303]]', 'An easy forest-road walk to Rifugio Città di Fiume, then a short, steep grassy ridge to a panoramic top right beneath the soaring north walls of Monte Pelmo, with views to Civetta, Antelao and the Marmolada.'),
  (1, 'croda-negra', 'Croda Negra from Passo Falzarego', 'Falzarego / Cortina d’Ampezzo', 'No. 441 / 442', 'easy', 6.2, 415, 2.5, 2518, 'Croda Negra', 'Nuvolau / Averau', 'Drive to Passo Falzarego (2,105 m); park at the Lagazuoi lift', 46.518, 12.0057, 46.5034, 12.025, '[[46.518,12.0057],[46.5151,12.0098],[46.5118,12.0142],[46.5085,12.0185],[46.5058,12.0221],[46.5034,12.025]]', 'Trail 441 across alpine meadows, then right onto the rocky path with one brief 2 m rock step before the airy summit ridge. On top, the sheer Tofane wall fills the horizon with the Cinque Torri towers in the valley below.'),
  (1, 'monte-cernera', 'Monte Cernera via Passo Giau', 'Passo Giau / Colle Santa Lucia', 'No. 436', 'medium', 6, 480, 4, 2664, 'Monte Cernera', 'Cernera / Ampezzo Dolomites', 'Drive to Passo Giau (2,236 m) on the SP638', 46.4825, 12.0535, 46.4681, 12.058, '[[46.4825,12.0535],[46.479,12.054],[46.4748,12.056],[46.4715,12.0572],[46.4698,12.0578],[46.4681,12.058]]', 'A green, panoramic traverse above Passo Giau on trail 436 — left fork to Forcella Giau, right to the Cernera — then two short, easy cable-protected pitches onto the broad summit plateau at 2,664 m, facing the Tofane.'),
  (1, 'monte-coldai', 'Monte Coldai (Cima Coldai)', 'Civetta / Val di Zoldo', 'No. 564 / 556', 'medium', 12.4, 875, 4.7, 2403, 'Cima Coldai', 'Civetta', 'Drive to Palafavera, Val di Zoldo (1,507 m); free parking', 46.4014, 12.1031, 46.4026, 12.0639, '[[46.4014,12.1031],[46.4025,12.1017],[46.401,12.089],[46.3994,12.0689],[46.3987,12.0611],[46.4007,12.0623],[46.4026,12.0639]]', 'A wide gravel road from Palafavera past Malga Pioda to Rifugio Sonino al Coldai, then up to the saddle above the turquoise Lago Coldai; a faint path opposite the lake gains the 2,403 m summit, set straight against the immense north-west wall of the Civetta.'),
  (1, 'seceda-pieralongia-col-raiser', 'Seceda – Pieralongia – Col Raiser', 'Puez-Odle Nature Park', 'No. 2b / 1', 'easy', 4.2, 90, 1.5, 2493, 'Seceda', 'Odle / Geisler', 'Seceda cable car from Ortisei up; Col Raiser gondola down', 46.5979, 11.7243, 46.5972, 11.7477, '[[46.5979,11.7243],[46.5998,11.7363],[46.5995,11.7404],[46.5988,11.7446],[46.5972,11.7477],[46.5965,11.7495],[46.5913,11.7436],[46.5848,11.7453]]', 'A near-level balcony walk from the Seceda top station beneath the Fermeda towers to the Pieralongia rock pinnacles and their little hut, then gently down meadow pastures to the Col Raiser gondola. Mostly downhill, family-friendly, with non-stop views of the most iconic ridgeline in the Dolomites.'),
  (1, 'tre-cime-loop', 'Tre Cime di Lavaredo Loop', 'Tre Cime Nature Park / Sexten Dolomites', 'No. 101 / 105', 'medium', 10, 400, 3.5, 2454, 'Forcella Lavaredo', 'Tre Cime di Lavaredo', 'Toll road from Misurina to Rifugio Auronzo (2,320 m)', 46.6122, 12.2961, 46.6225, 12.3115, '[[46.6122,12.2961],[46.6183,12.3121],[46.6225,12.3115],[46.6369,12.3106],[46.63,12.3],[46.618,12.296],[46.6122,12.2961]]', 'The wide, hugely popular circuit that rounds the north faces of the Tre Cime, climbing gently over the Forcella Lavaredo saddle to Rifugio Locatelli, where the three sheer towers line up in their iconic profile. Only ~400 m of ascent, but a proper mountain day at 2,300–2,450 m.'),
  (1, 'lago-di-sorapis', 'Lago di Sorapis', 'Sorapiss / Cortina d’Ampezzo', 'No. 215', 'medium', 12, 600, 4, 1925, 'Lago di Sorapis', 'Sorapiss', 'Car or summer bus from Cortina to Passo Tre Croci (1,809 m)', 46.557, 12.2019, 46.5206, 12.2233, '[[46.557,12.2019],[46.549,12.207],[46.541,12.212],[46.534,12.2185],[46.529,12.225],[46.5217,12.2266],[46.5206,12.2233]]', 'From Passo Tre Croci, trail 215 starts gently through larch forest, then narrows into rocky balcony ledges secured with cables and iron steps before dropping to the milky-turquoise Lago di Sorapis beneath the Dito di Dio spire. Hugely popular — the exposed sections want sure feet.'),
  (1, 'lago-di-braies', 'Lago di Braies Lake Circuit', 'Prags / Braies, South Tyrol', 'No. 1', 'easy', 3.6, 45, 1.25, 1496, 'Lago di Braies', 'Croda del Becco / Seekofel', 'Summer 9–16h car closure: pre-book parking or shuttle bus', 46.6988, 12.0845, 46.6947, 12.0858, '[[46.6988,12.0845],[46.6975,12.083],[46.6955,12.082],[46.693,12.0815],[46.6905,12.0825],[46.69,12.085],[46.692,12.087],[46.695,12.0878],[46.6975,12.0865],[46.6988,12.0845]]', 'An easy, near-flat loop around the emerald Pragser Wildsee — the "pearl of the Dolomite lakes" — beneath the Croda del Becco. Wide gravel and boardwalk on the west shore, a few rocky steps on the far side, and the famous wooden boathouse at the start.'),
  (1, 'cinque-torri', 'Giro delle Cinque Torri', 'Cortina d’Ampezzo / Falzarego', 'No. 439 / 440 / 425', 'easy', 3.5, 150, 2, 2255, 'Rifugio Scoiattoli', 'Nuvolau / Averau', '5 Torri chairlift from Bai de Dones (1,889 m), or walk up ~1 h', 46.5081, 12.0468, 46.5089, 12.0519, '[[46.5081,12.0468],[46.509,12.048],[46.5093,12.0518],[46.5089,12.0519],[46.5082,12.0548],[46.5079,12.051],[46.5081,12.0468]]', 'A gentle lift-assisted circuit around the five Dolomite towers — Torre Grande tops out at 2,361 m, climbers only — threading the restored WWI trenches and gun posts of the open-air Great War museum, with the Tofane and Croda da Lago all around.'),
  (1, 'selva-rifugio-puez', 'Selva → Rifugio Puez (Crespeina Plateau)', 'Puez-Odle Nature Park', 'Alta Via 2 / No. 12A, 2, 16, 14', 'medium', 15.5, 600, 6, 2528, 'Passo Crespeina', 'Puez Group', 'Dantercepies gondola from Selva di Val Gardena', 46.554, 11.8, 46.5901, 11.8292, '[[46.554,11.8],[46.5611,11.8159],[46.5646,11.8228],[46.5684,11.8254],[46.577,11.8376],[46.5901,11.8292],[46.573,11.797],[46.5678,11.7828]]', 'A committing high-alpine day on the lunar Puez plateau: from the Dantercepies gondola over Passo Cir and Passo Crespeina (2,528 m), past the emerald Lago di Crespeina to Rifugio Puez, returning down the long, dramatic Vallunga valley to Selva. No via ferrata — just distance, altitude and weather.');
